@page "/apply"
@rendermode InteractiveServer
@using sv_fd32c47b23414b76a9a0784462ba508f.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < CurrentStep)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (i < StepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @* Validation Errors *@
    @if (Errors.Count > 0)
    {
        <div class="validation-errors">
            <ul>
                @foreach (var error in Errors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    @* Step Content *@
    @if (!IsSubmitted)
    {
        @switch (CurrentStep)
        {
            case 0:
                @RenderPersonalInfo();
                break;
            case 1:
                @RenderWorkHistory();
                break;
            case 2:
                @RenderReferences();
                break;
            case 3:
                @RenderCoverLetter();
                break;
            case 4:
                @RenderReview();
                break;
        }
    }
    else
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your application ID is <strong>#@SubmittedApplicationId</strong>.</p>
            <p>We will review your application and get back to you soon.</p>
        </div>
    }
</div>

@* Step 1: Personal Info *@
@{
    RenderFragment RenderPersonalInfo() => __builder =>
    {
        <div class="step-content">
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" @bind="FullName" placeholder="Enter your full name" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" @bind="Email" placeholder="Enter your email" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" @bind="Phone" placeholder="Enter your phone number" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <input id="address" type="text" @bind="Address" placeholder="Enter your address" />
            </div>
            <div class="step-buttons">
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    };
}

@* Step 2: Work History *@
@{
    RenderFragment RenderWorkHistory() => __builder =>
    {
        <div class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < WorkEntries.Count; i++)
            {
                var index = i;
                <div class="work-entry-card">
                    <div class="work-entry-header">
                        <h3>Position @(index + 1)</h3>
                        @if (WorkEntries.Count > 1)
                        {
                            <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="WorkEntries[index].Company" placeholder="Company name" />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="WorkEntries[index].Title" placeholder="Job title" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Start Date *</label>
                            <input type="date" @bind="WorkEntries[index].StartDate" />
                        </div>
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="WorkEntries[index].EndDate" disabled="@WorkEntries[index].IsCurrent" />
                        </div>
                    </div>
                    <div class="form-group checkbox-group">
                        <input type="checkbox" id="current-@index" @bind="WorkEntries[index].IsCurrent" />
                        <label for="current-@index">I currently work here</label>
                    </div>
                    <div class="form-group">
                        <label>Description</label>
                        <textarea @bind="WorkEntries[index].Description" placeholder="Describe your responsibilities..." rows="3"></textarea>
                    </div>
                </div>
            }
            <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="step-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    };
}

@* Step 3: References *@
@{
    RenderFragment RenderReferences() => __builder =>
    {
        <div class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < References.Count; i++)
            {
                var index = i;
                <div class="reference-card">
                    <div class="work-entry-header">
                        <h3>Reference @(index + 1)</h3>
                        @if (References.Count > 2)
                        {
                            <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" @bind="References[index].Name" placeholder="Reference name" />
                    </div>
                    <div class="form-group">
                        <label>Relationship *</label>
                        <input type="text" @bind="References[index].Relationship" placeholder="e.g., Former Manager" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="References[index].Email" placeholder="Reference email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="References[index].Phone" placeholder="Reference phone" />
                    </div>
                </div>
            }
            @if (References.Count < 3)
            {
                <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="step-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    };
}

@* Step 4: Cover Letter *@
@{
    RenderFragment RenderCoverLetter() => __builder =>
    {
        <div class="step-content">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter</label>
                <textarea id="coverLetter" @bind="CoverLetter" @bind:event="oninput" placeholder="Tell us why you'd be a great fit..." rows="12" maxlength="2000"></textarea>
                <div class="char-count">@CoverLetter.Length / 2000 characters</div>
            </div>
            <div class="step-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    };
}

@* Step 5: Review & Submit *@
@{
    RenderFragment RenderReview() => __builder =>
    {
        <div class="step-content">
            <h2>Review &amp; Submit</h2>

            <div class="review-section">
                <div class="review-header">
                    <h3>Personal Information</h3>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(0)'>Edit</a>
                </div>
                <dl>
                    <dt>Full Name</dt><dd>@FullName</dd>
                    <dt>Email</dt><dd>@Email</dd>
                    <dt>Phone</dt><dd>@Phone</dd>
                    <dt>Address</dt><dd>@Address</dd>
                </dl>
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Work History</h3>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(1)'>Edit</a>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <span>@entry.StartDate.ToString("MMM yyyy") &mdash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>References</h3>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(2)'>Edit</a>
                </div>
                @foreach (var r in References)
                {
                    <div class="review-entry">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <span>@r.Email | @r.Phone</span>
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Cover Letter</h3>
                    <a href="javascript:void(0)" @onclick='() => NavigateToStep(3)'>Edit</a>
                </div>
                <p class="cover-letter-preview">@CoverLetter</p>
            </div>

            <div class="step-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-submit" @onclick="SubmitApplication" disabled="@IsSubmitting">
                    @(IsSubmitting ? "Submitting..." : "Submit Application")
                </button>
            </div>
        </div>
    };
}

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private List<string> Errors { get; set; } = new();
    private bool IsSubmitting { get; set; }
    private bool IsSubmitted { get; set; }
    private int SubmittedApplicationId { get; set; }

    // Step 1 fields
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;

    // Step 2 fields
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3 fields
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 fields
    private string CoverLetter { get; set; } = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex < CurrentStep) return "completed";
        return "dimmed";
    }

    private void NavigateToStep(int step)
    {
        if (step < CurrentStep)
        {
            Errors.Clear();
            CurrentStep = step;
        }
    }

    private async Task NextStep()
    {
        Errors.Clear();

        if (!await ValidateCurrentStep())
            return;

        CurrentStep++;
    }

    private void PreviousStep()
    {
        Errors.Clear();
        if (CurrentStep > 0)
            CurrentStep--;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName)) Errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(Email)) Errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(Phone)) Errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(Address)) Errors.Add("Address is required.");
                if (Errors.Count == 0 && !string.IsNullOrWhiteSpace(Email))
                {
                    var isValid = await ApplicationService.ValidateEmailAsync(Email);
                    if (!isValid) Errors.Add("The email address is not valid.");
                }
                break;

            case 1:
                for (int i = 0; i < WorkEntries.Count; i++)
                {
                    var entry = WorkEntries[i];
                    if (string.IsNullOrWhiteSpace(entry.Company)) Errors.Add($"Position {i + 1}: Company name is required.");
                    if (string.IsNullOrWhiteSpace(entry.Title)) Errors.Add($"Position {i + 1}: Job title is required.");
                    if (entry.StartDate == default) Errors.Add($"Position {i + 1}: Start date is required.");
                }
                break;

            case 2:
                for (int i = 0; i < References.Count; i++)
                {
                    var r = References[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) Errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) Errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) Errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) Errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;

            case 3:
                // Cover letter is optional, no validation required
                break;
        }

        return Errors.Count == 0;
    }

