.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.875rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.3s ease;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #2ecc71;
    background: #2ecc71;
    color: #fff;
}

.step.dimmed .step-circle {
    border-color: #ddd;
    background: #f5f5f5;
    color: #bbb;
}

.step-label {
    font-size: 0.75rem;
    margin-top: 0.5rem;
    text-align: center;
    color: #666;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ecc71;
}

.step.dimmed .step-label {
    color: #bbb;
}

.step-connector {
    width: 40px;
    height: 2px;
    background: #ddd;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #2ecc71;
}

/* Validation Errors */
.validation-errors {
    background: #fdecea;
    border: 1px solid #f5c6cb;
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1.5rem;
}

.validation-errors ul {
    margin: 0;
    padding-left: 1.25rem;
    color: #c0392b;
}

.validation-errors li {
    margin-bottom: 0.25rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Groups */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    color: #333;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.checkbox-group input[type="checkbox"] {
    width: auto;
}

.checkbox-group label {
    display: inline;
    margin-bottom: 0;
    font-weight: normal;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h3 {
    margin: 0;
    color: #444;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn-next,
.btn-submit {
    background: #4361ee;
    color: #fff;
    border: none;
    padding: 0.7rem 2rem;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
    margin-left: auto;
}

.btn-next:hover,
.btn-submit:hover {
    background: #3651d4;
}

.btn-submit:disabled {
    background: #a0aec0;
    cursor: not-allowed;
}

.btn-back {
    background: transparent;
    color: #666;
    border: 1px solid #ddd;
    padding: 0.7rem 2rem;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-back:hover {
    background: #f5f5f5;
    border-color: #ccc;
}

.btn-add {
    background: transparent;
    color: #4361ee;
    border: 1px dashed #4361ee;
    padding: 0.6rem 1.5rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.2s;
    margin-top: 0.5rem;
}

.btn-add:hover {
    background: #eef1ff;
}

.btn-remove {
    background: transparent;
    color: #e74c3c;
    border: 1px solid #e74c3c;
    padding: 0.35rem 0.75rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-remove:hover {
    background: #fdecea;
}

/* Character Count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.4rem;
}

/* Review Section */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    color: #333;
}

.review-header a {
    color: #4361ee;
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 500;
}

.review-header a:hover {
    text-decoration: underline;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
}

.review-section dd {
    margin: 0;
    color: #333;
}

.review-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #eee;
}

.review-entry:last-child {
    border-bottom: none;
    padding-bottom: 0;
}

.cover-letter-preview {
    white-space: pre-wrap;
    color: #444;
    line-height: 1.6;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 12px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.confirmation h2 {
    color: #2ecc71;
    font-size: 1.75rem;
    margin-bottom: 1rem;
}

.confirmation p {
    color: #555;
    font-size: 1.1rem;
}

