+}
+
+.btn-next,
+.btn-submit {
+    background: #4361ee;
+    color: #fff;
+    border: none;
+    padding: 0.7rem 2rem;
+    border-radius: 6px;
+    font-size: 0.95rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.2s;
+    margin-left: auto;
+}
+
+.btn-next:hover,
+.btn-submit:hover {
+    background: #3651d4;
+}
+
+.btn-submit:disabled {
+    background: #a0aec0;
+    cursor: not-allowed;
+}
+
+.btn-back {
+    background: transparent;
+    color: #666;
+    border: 1px solid #ddd;
+    padding: 0.7rem 2rem;
+    border-radius: 6px;
+    font-size: 0.95rem;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+.btn-back:hover {
+    background: #f5f5f5;
+    border-color: #ccc;
+}
+
+.btn-add {
+    background: transparent;
+    color: #4361ee;
+    border: 1px dashed #4361ee;
+    padding: 0.6rem 1.5rem;
+    border-radius: 6px;
+    font-size: 0.9rem;
+    cursor: pointer;
+    transition: all 0.2s;
+    margin-top: 0.5rem;
+}
+
+.btn-add:hover {
+    background: #eef1ff;
+}
+
+.btn-remove {
+    background: transparent;
+    color: #e74c3c;
+    border: 1px solid #e74c3c;
+    padding: 0.35rem 0.75rem;
+    border-radius: 4px;
+    font-size: 0.8rem;
