+
+.review-section dt {
+    font-weight: 500;
+    color: #666;
+}
+
+.review-section dd {
+    margin: 0;
+    color: #333;
+}
+
+.review-entry {
+    padding: 0.75rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-entry:last-child {
+    border-bottom: none;
+    padding-bottom: 0;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
